/**
 * Operator-flow eval: do the panel's buttons agree with the real backend?
 *
 * Reads ../contract/state-matrix.json, which the Python backend generated by
 * driving GameController into every phase. Run: node services/web/evals/flows.mjs
 *
 * - sound: a control the UI enables is one the backend accepts (no 409 clicks).
 * - complete: with the projector open, every control the backend accepts is
 *   enabled, so the operator is never stuck behind a disabled button.
 * - no_camera: without a live camera, nothing that needs a frame is enabled.
 * - journey: the moves an operator needs are enabled where they need them.
 * - reopen: every phase with the projector closed recovers after J.
 */

import { readFileSync } from "node:fs";
import { pathToFileURL } from "node:url";

import { controlsFor } from "../ui/ui-core.mjs";

const matrix = JSON.parse(readFileSync(new URL("../contract/state-matrix.json", import.meta.url), "utf8"));
const CONTROLS = ["scan", "calibrate", "launch", "aim", "reset", "resume"];
const NEEDS_CAMERA = ["scan", "calibrate", "launch"];
const JOURNEY = [
  ["waiting_camera", "scan"],
  ["scanned", "calibrate"],
  ["ready", "aim"],
  ["ready", "launch"],
  ["running", "reset"],
  ["won", "reset"],
  ["won", "scan"],
  ["lost", "reset"],
  ["paused_open", "resume"],
  ["paused_open", "scan"],
  ["paused_open", "calibrate"],
];
const REOPEN = { projector_closed: "waiting_camera", ready_closed: "ready", paused_closed: "paused_open" };

function uiControls(state, cameraReady = true) {
  return controlsFor(state, cameraReady, Boolean(state.projection.open));
}

function phaseCase(name, { state, accepts }) {
  const ui = uiControls(state);
  const noCamera = uiControls(state, false);
  const unsound = CONTROLS.filter((c) => ui[c] && !accepts[c]);
  const missing = state.projection.open ? CONTROLS.filter((c) => accepts[c] && !ui[c]) : [];
  const cameraLeak = NEEDS_CAMERA.filter((c) => noCamera[c]);
  return {
    case: `phase:${name}`,
    passed: unsound.length + missing.length + cameraLeak.length === 0,
    ui_enabled: CONTROLS.filter((c) => ui[c]),
    backend_accepts: CONTROLS.filter((c) => accepts[c]),
    unsound,
    missing,
    camera_leak: cameraLeak,
  };
}

function journeyCase() {
  const blocked = JOURNEY
    .filter(([phase, control]) => {
      const { state, accepts } = matrix.phases[phase];
      return !(uiControls(state)[control] && accepts[control]);
    })
    .map(([phase, control]) => `${phase}:${control}`);
  return { case: "journey", passed: blocked.length === 0, steps: JOURNEY.length, blocked };
}

function reopenCase() {
  const stuck = Object.entries(REOPEN)
    .filter(([closed, open]) => {
      const before = matrix.phases[closed].state;
      const after = matrix.phases[open].state;
      const sameAttempt = before.game.status === after.game.status && before.game.paused === after.game.paused;
      const anyEnabled = CONTROLS.some((c) => uiControls(after)[c]);
      return before.projection.open || !after.projection.open || !sameAttempt || !anyEnabled;
    })
    .map(([closed]) => closed);
  return { case: "reopen", passed: stuck.length === 0, stuck };
}

export function runEval() {
  const cases = [
    ...Object.entries(matrix.phases).map(([name, row]) => phaseCase(name, row)),
    journeyCase(),
    reopenCase(),
  ];
  const passed = cases.filter((c) => c.passed).length;
  return {
    score: Number((passed / cases.length).toFixed(3)),
    pass_threshold: 1.0,
    disagreements: cases.reduce((n, c) => n + (c.unsound?.length ?? 0) + (c.missing?.length ?? 0), 0),
    cases,
  };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const report = runEval();
  console.log(JSON.stringify(report, null, 2));
  process.exitCode = report.score >= report.pass_threshold ? 0 : 1;
}
